const basis = JSON.stringify(n01);
const usr = 'Bewerte die Automatisierungsreife des Vorhabens anhand von 8 Kriterien (Standardisierung, Regelbasiertheit, Datenverfuegbarkeit, Volumen/Haeufigkeit, Fehleranfaelligkeit heute, Schnittstellen, Stabilitaet des Prozesses, Akzeptanz). Vergib pro Kriterium 0-10 und einen Gesamtscore 0-10. Gib IMMER einen Gesamtscore ab, auch bei duenner Datenlage (dann konservativ schaetzen, art=Annahme). Antworte niemals leer.\n\n' +
'Uebernimm KEINE Kennzeichnungen oder Felder aus N01 - liefere nur deine eigene Reife-Bewertung.\n\n' +
'JSON-Schema: {"score":0,"kriterien":[{"name":"","wert":0,"begruendung":""}],"konfidenz":0.0,' +
'"luecken":[{"was":"","wo":"N02","konsequenz":""}]}\n\n=== KONTEXT (N01) ===\n' + basis;
return [{ json: { requestBody: {
