'\n\n=== TRANSKRIPT (fuer konkrete Zahlen/Zeiten) ===\n' + (ctx.transcript || '(keine Aufnahme)');
return [{ json: { requestBody: {
  model: cfg.llm_model, temperature: cfg.temperature,
