  (n05b && n05b.begruendung ? '<div style="background:#f8fafb;border:1px solid #e8eef3;border-radius:8px;padding:10px 12px;margin-top:8px;font-size:13px">' + esc(n05b.begruendung) + '</div>' : '') +
  (vorlaeufig ? '<div style="background:#fff3cd;border-left:5px solid #e0a800;border-radius:8px;padding:10px 14px;margin-top:8px;font-size:12px;color:#7a5c00"><strong>Vorlaeufig:</strong> Diese Kennzahlen gelten bis zum bestandenen Vergleichstest (lokal vs. Cloud, JC-06) als Schaetzung. Erst danach werden sie als final ausgewiesen, und die Empfehlung kann ueber "Pilotieren" hinausgehen.</div>' : '') +
  '<h2>Score-Zusammensetzung (regelbasiert, N08a)</h2><table><thead><tr><th>Dimension</th><th style="text-align:center">Score</th><th style="text-align:right">Gewicht</th></tr></thead><tbody>' + scoreRows + '</tbody></table>' +
  '<div style="font-size:11px;color:#888;margin-top:6px">' + esc(a.regelwerk) + '</div>' +
  '<div class="page-break"></div><h2>Detailanalyse je Node</h2>' +
  detail('N01 Kontext & Prozess', n01) + detail('N02 Automatisierungsreife', n02) + detail('N03 Direkter Nutzen', n03) +
  detail('N04 Vollkosten', n04) + detail('N05 Nutzen-Kosten / ROI', n05) + detail('N06 Umsetzbarkeit', n06) + detail('N07 Risiko & Compliance', n07) +
  '<div class="page-break"></div><h2>Lueckenliste (N09)</h2><table><thead><tr><th>#</th><th>Was fehlt</th><th>Node</th><th>Konsequenz</th></tr></thead><tbody>' + lueckenRows + '</tbody></table>' +
  '<h2 style="margin-top:22px">Glossar</h2>' + glossarHtml +
  '<div style="margin-top:24px;padding-top:12px;border-top:1px solid #eee;font-size:11px;color:#999;text-align:center">KI-Wirtschaftlichkeits-Check &middot; ' + esc(ctx.unternehmen) + ' &middot; ' + esc(ctx.datum) + ' &middot; Verarbeitung self-hosted & DSGVO-konform</div>' +
  '</body></html>';
const safe = (s) => String(s||'Unternehmen').replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,40);
const fileName = 'Wirtschaftlichkeits-Check_' + safe(ctx.unternehmen) + '_' + ctx.datum + '.pdf';
return [{ json: { fileName, unternehmen: ctx.unternehmen },
  binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } } }];
